func runMemoryLoopRefresh(ctx context.Context, w io.Writer, last int, scopeArg, branchArg string, debug bool) error {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("not in a git repository: %w", err)
	}

	cfg, cfgErr := LoadEntireSettings(ctx)
	if cfgErr != nil {
		return fmt.Errorf("load settings: %w", cfgErr)
	}

	idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
	if err != nil {
		return fmt.Errorf("open insights cache: %w", err)
	}
	defer func() { _ = idb.Close() }()

	renderMemoryLoopRefreshProgress(w, "Refreshing cache...")
	refreshCacheIfStale(ctx, idb) //nolint:errcheck,gosec // non-fatal

	scope, err := resolveMemoryLoopScope(ctx, scopeArg, branchArg)
	if err != nil {
		return err
	}

	switch scope.Mode {
	case memoryLoopScopeRepo, memoryLoopScopeBranch:
		renderMemoryLoopRefreshProgress(w, fmt.Sprintf("Scope: %s (branch: %s)", scope.Mode, scope.Branch))
	case memoryLoopScopeMe:
		renderMemoryLoopRefreshProgress(w, fmt.Sprintf("Scope: me (%s)", scope.OwnerID))
	}

	renderMemoryLoopRefreshProgress(w, "Loading scoped sessions...")
	rows, err := queryMemoryLoopRows(ctx, idb, scope, last)
	if err != nil {
		return fmt.Errorf("query sessions: %w", err)
	}

	if settings.IsSummarizeEnabled(ctx) && len(rows) > 0 {
		renderMemoryLoopRefreshProgress(w, "Backfilling summaries for scoped sessions...")
		backfillSessionRows(ctx, w, idb, rows, debug)
	}

	// Re-query to pick up backfilled data.
	rows, err = queryMemoryLoopRows(ctx, idb, scope, last)
	if err != nil {
		return fmt.Errorf("query sessions: %w", err)
	}
	if len(rows) == 0 {
		if err := renderEmptyMemoryLoopScopeMessage(ctx, w, idb, scope); err != nil {
			return err
		}
		return nil
	}

	analysis := improve.AnalyzePatterns(sessionRowsToSummaries(rows))

	memoryCfg := cfg.GetMemoryLoopConfig()
	thresholdPreset := memoryCfg.GenerationThreshold
	if thresholdPreset == "" {
		thresholdPreset = "balanced"
	}
	var thresholdOverrides *memoryloop.GenerationThresholdOverrides
	if memoryCfg.GenerationOverrides != nil {
		thresholdOverrides = &memoryloop.GenerationThresholdOverrides{
			MinStrength:      memoryCfg.GenerationOverrides.MinStrength,
			MinConfidence:    memoryCfg.GenerationOverrides.MinConfidence,
			EvidenceSessions: memoryCfg.GenerationOverrides.EvidenceSessions,
			GenericFilter:    memoryCfg.GenerationOverrides.GenericFilter,
			SingletonPolicy:  memoryCfg.GenerationOverrides.SingletonPolicy,
		}
	}
	thresholdCfg := memoryloop.ResolveGenerationThreshold(thresholdPreset, thresholdOverrides)

	gen := memoryloop.Generator{Runner: &llmcli.Runner{}}
	renderMemoryLoopRefreshProgress(w, "Distilling memories...")
	records, generationStats, usage, err := gen.Generate(ctx, memoryloop.GenerateInput{
		Analysis:        analysis,
		Sessions:        rows,
		SourceWindow:    last,
		MaxRecords:      memoryloop.DefaultMaxRecords,
		ThresholdConfig: thresholdCfg,
	})
	if err != nil {
		return fmt.Errorf("generate memory snapshot: %w", err)
	}

	state, err := loadMemoryLoopState(ctx)
	if err != nil {
		return fmt.Errorf("load memory-loop state: %w", err)
	}

	maxInjected := memoryCfg.MaxInjected
	mode := memoryloop.Mode(memoryCfg.Mode)
	storeDebug := memoryCfg.Debug
	activationPolicy := memoryloop.ActivationPolicy(memoryCfg.ActivationPolicy)
	if state.Store != nil {
		if state.Store.Mode != "" {
			mode = state.Store.Mode
		}
		storeDebug = state.Store.Debug
		if state.Store.MaxInjected > 0 {
			maxInjected = state.Store.MaxInjected
		}
		if state.Store.ActivationPolicy != "" {
			activationPolicy = state.Store.ActivationPolicy
		}
	}

	now := time.Now().UTC()
	scopeValue := scopeValue(scope)
	renderMemoryLoopRefreshProgress(w, "Reconciling with existing memory history...")
	reconcile := memoryloop.ReconcileGeneratedRecords(
		existingMemoryRecords(state),
		records,
		scopeKindForRefresh(scope),
		scopeValue,
		activationPolicy,
		now,
	)
	reconcile.History.Scope = string(scope.Mode)
	reconcile.History.SourceWindow = last
	reconcile.History.FilteredWeakCount = generationStats.FilteredWeakCount
	reconcile.History.FilteredGenericCount = generationStats.FilteredGenericCount
	reconcile.History.FilteredNoEvidenceCount = generationStats.FilteredNoEvidenceCount
	reconcile.History.DedupedCount = generationStats.DedupedCount
	reconcile.History.Threshold = thresholdPreset
	reconcile.History.ThresholdOverride = thresholdOverrides != nil
	reconcile.History.ResolvedConfig = &thresholdCfg
	refreshHistory := append(existingRefreshHistory(state), reconcile.History)
	reconciledRecords := memoryloop.DeriveOutcomes(reconcile.Records, rows, now)
	reconciledRecords, pruneResult := memoryloop.PruneRecords(reconciledRecords, now)
	if len(refreshHistory) > 0 {
		lastIdx := len(refreshHistory) - 1
		refreshHistory[lastIdx].DemotedCount = pruneResult.DemotedCount
		refreshHistory[lastIdx].PrunedCount = pruneResult.PrunedCount
		if usage != nil {
			refreshHistory[lastIdx].InputTokens = usage.InputTokens
			refreshHistory[lastIdx].OutputTokens = usage.OutputTokens
			refreshHistory[lastIdx].TotalCostUSD = usage.TotalCostUSD
		}
	}

	state.Store = &memoryloop.Store{
		Version:          1,
		GeneratedAt:      now,
		SourceWindow:     last,
		Scope:            string(scope.Mode),
		ScopeValue:       scopeValue,
		Records:          reconciledRecords,
		Mode:             mode,
		Debug:            storeDebug,
		ActivationPolicy: activationPolicy,
		MaxInjected:      maxInjected,
		RefreshHistory:   refreshHistory,
	}

	renderMemoryLoopRefreshProgress(w, "Saving memory store...")
	if err := memoryloop.SaveState(ctx, state); err != nil {
		return fmt.Errorf("save memory-loop state: %w", err)
	}

	activeCount, candidateCount, suppressedCount, archivedCount := countMemoryStatuses(reconciledRecords)
	generatedTitles := make([]string, 0, len(records))
	for _, record := range records {
		if title := strings.TrimSpace(record.Title); title != "" {
			generatedTitles = append(generatedTitles, title)
		}
	}
	renderMemoryLoopRefreshSummary(w, memoryLoopRefreshSummary{
		SessionCount:         len(rows),
		ScopeLabel:           formatMemoryLoopScopeLabel(scope),
		GeneratedCount:       reconcile.History.GeneratedCount,
		ActivatedCount:       reconcile.History.ActivatedCount,
		CandidateCount:       reconcile.History.CandidateCount,
		ActiveCount:          activeCount,
		StoredCandidateCount: candidateCount,
		SuppressedCount:      suppressedCount,
		ArchivedCount:        archivedCount,
		GeneratedTitles:      generatedTitles,
	})
	if usage != nil {
		renderUsageLine(w, usage)
	}

	return nil
}

func existingMemoryRecords(state *memoryloop.State) []memoryloop.MemoryRecord {
	if state == nil || state.Store == nil {
		return nil
	}
	return state.Store.Records
}

func existingRefreshHistory(state *memoryloop.State) []memoryloop.RefreshHistory {
	if state == nil || state.Store == nil {
		return nil
	}
	return append([]memoryloop.RefreshHistory(nil), state.Store.RefreshHistory...)
}

